  wr_data,
  rd_data,
  rd_data_valid,
  addr,
  cmd,
  cmd_en,
  cmd_rdy,
  init_calib,
  clk_out,
  data_mask
)
;
input clk;
input memory_clk;
input pll_lock;
input rst_n;
output [1:0] O_psram_ck;
output [1:0] O_psram_ck_n;
inout [15:0] IO_psram_dq;
inout [1:0] IO_psram_rwds;
output [1:0] O_psram_cs_n;
