input [63:0] wr_data;
output [63:0] rd_data;
output rd_data_valid;
input [20:0] addr;
input cmd;
input cmd_en;
output cmd_rdy;
output init_calib;
output clk_out;
input [7:0] data_mask;
wire VCC;
wire GND;
  \~psram_top.PSRAM_Memory_Interface_HS_Top  u_psram_top (
    .memory_clk(memory_clk),
    .rst_n(rst_n),
    .pll_lock(pll_lock),
    .cmd(cmd),
    .cmd_en(cmd_en),
    .clk(clk),
    .wr_data(wr_data[63:0]),
